<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="robots" content="noindex,nofollow"><meta name="color-scheme" content="dark"><title>{{ $code }} · Private Gather</title>
<style>
:root{color-scheme:dark;--bg:#09090c;--panel:#131218;--line:#2a2730;--gold:#d9bc78;--text:#f5f0e8;--muted:#aaa3ad}*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;padding:24px;background:radial-gradient(circle at 70% 10%,#352034 0,transparent 34%),linear-gradient(145deg,#09090c,#100d13 62%,#080809);font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:var(--text)}main{width:min(760px,100%);border:1px solid var(--line);border-radius:28px;padding:clamp(28px,7vw,64px);background:rgba(19,18,24,.94);box-shadow:0 32px 90px rgba(0,0,0,.38)}.mark{display:inline-grid;place-items:center;width:58px;height:58px;border:1px solid rgba(217,188,120,.5);border-radius:50%;color:var(--gold);font-family:Georgia,serif;font-size:24px;margin-bottom:26px}.eyebrow{color:var(--gold);font-size:12px;font-weight:800;letter-spacing:.18em}.code{font-size:clamp(64px,15vw,126px);line-height:.82;margin:14px 0 22px;font-family:Georgia,"Times New Roman",serif;font-weight:500;letter-spacing:-.06em}.code span{color:var(--gold)}h1{font-size:clamp(27px,5vw,44px);margin:0 0 14px}p{color:var(--muted);font-size:17px;line-height:1.65;max-width:600px}.actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:28px}a,button{appearance:none;text-decoration:none;border:1px solid var(--line);background:#1b1820;color:var(--text);border-radius:999px;padding:12px 18px;font-weight:750;font:inherit;cursor:pointer}a.primary{background:var(--gold);border-color:var(--gold);color:#17120a}small{display:block;margin-top:28px;color:#77717c;line-height:1.5}@media(max-width:520px){main{border-radius:20px;padding:30px 22px}.actions>*{width:100%;text-align:center}}
</style>
</head><body><main><div class="mark" aria-hidden="true">PG</div><div class="eyebrow">PRIVATE GATHER · {{ $eyebrow }}</div><div class="code"><span>{{ $code }}</span></div><h1>{{ $title }}</h1><p>{{ $message }}</p><div class="actions"><a class="primary" href="/">Private Gather home</a><button type="button" onclick="history.length>1?history.back():location.assign('/')">Go back</button></div><small>{{ $help }}</small></main></body></html>
